import{z as n,x as i,o as r,c as d,q as t,j as B,D as A,d as a,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"LLM-as-judge 的深化","description":"","frontmatter":{"title":"LLM-as-judge 的深化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ef-llm-judge-deep.md","filePath":"llm/ef-llm-judge-deep.md","lastUpdated":1791063341000}'),p={name:"llm/ef-llm-judge-deep.md"};function m(u,E,h,g,D,F){const l=i("Mermaid");return r(),d("div",null,[E[2]||(E[2]=t('<h1 id="llm-as-judge-的深化" tabindex="-1">LLM-as-judge 的深化 <a class="header-anchor" href="#llm-as-judge-的深化" aria-label="Permalink to &quot;LLM-as-judge 的深化&quot;">​</a></h1><div class="epigraph"><p>换序与控长只是让法官不作弊；把法官当仪器深化，是让它可标定：准则可操作、判决可拆解、一致率对人有交代。</p><footer>—— 据 Zheng 等 2023、Zhu 等 JudgeLM 2023、Kim 等 Prometheus 2023、Li 等 Auto-J 2023 整理</footer></div><p><a href="/llm/ade-map">上一课</a>把对齐数据工程收在一条主线上：定义写成锚，锚经数据变成边界，策略把边界放大成行为；数据的版本管理决定行为的漂移。边界立好、策略放大之后，行为的量法仍未解决：法官仍是一只被审计过的黑盒——<a href="/llm/llm-judge-bias">偏差课</a>给了换序、控长、双族对照这些最低工程，<a href="/llm/mt-bench">MT-Bench</a>把法官当误差的显微镜。本课是「评测前沿方法」的第一课，写法官本身的深化：把「哪条更好」拆成可判定的准则、改造判决结构、训练与集成法官、对人标定。后课的竞技场、组合与训练协同都默认法官已经是标定过的仪器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>未深化的法官只有一个输出：胜者或一个 1–10 分。它把事实、服从、文风、安全压成一次直觉判断，偏差无处归因：长回答赢了，不知赢在信息量还是排版；分数差零点几，不知是模型差还是法官抖。要优化的团队还会对法官直接做梯度上升——<a href="/llm/llm-judge-reward">裁判作奖励</a>已警告这会被 PPO 放大。<span class="marginnote">「对法官做梯度上升」就是把法官的打分当训练目标去优化被评的模型。风险在于法官自己也是语言模型、自带偏好：被评模型会学着专挑法官爱看的样子写（更长、更多列表、语气更自信），而不是真的变好——分数涨了，质量没涨。</span>缺口不是再补一条偏差清单，而是把判决变成<strong>可归因、可标定、可复算</strong>的测量。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>准则操作化</strong>是第一步：把「更好」写成几条可独立判定的命题——事实是否与参考一致、是否覆盖任务的每个子要求、是否执行了格式约束、是否引入了要求之外的伤害。每条准则单独输出「满足 / 不满足 / 无法判定」加一句证据，再聚合。这与 <a href="/llm/ifeval">IFEval</a> 同源：能程序判定的不交给语言直觉，法官只接程序判不了的部分。<strong>判决结构</strong>上，先让法官写证据再下结论，或对两答先各自评分再比较，避免把比较当第一反应；<strong>自采样</strong>取多次判决的多数，压随机抖动——但只压方差，不纠系统偏差。<strong>标定</strong>用人金标：留一批人与法官同判的样本，报一致率与 Cohen \\(\\kappa\\)，<span class="marginnote">Cohen \\(\\kappa\\) 可以这样读：从一致率里扣掉「纯属碰巧的一致」再归一。假如两人闭着眼乱判也能对上 50%，那表面 80% 的一致率其实只值 \\(\\kappa\\approx 0.6\\)。经验门槛：\\(\\kappa\\) 超过 0.8 算高度一致，0.4–0.6 算中等，低于 0.4 的法官不能上岗。</span>分歧样本送人仲裁并回流标定集。<strong>微调法官</strong>（Prometheus 一类）用公开的 rubric 与反馈语料把评分行为固化进权重；<strong>法官集成</strong>让不同家族的法官各判一遍，分歧即升级。</p>',7)),(r(),B(o,null,{default:A(()=>[s(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%9B%9E%E7%AD%94%E5%AF%B9%20%2F%20%E5%8D%95%E7%AD%94%22%5D%20--%3E%20B%5B%22rubric%20%E6%8B%86%E6%88%90%E5%8F%AF%E5%88%A4%E5%AE%9A%E5%87%86%E5%88%99%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%A8%8B%E5%BA%8F%E5%88%A4%E5%AE%9A%E5%AD%90%E9%9B%86%E5%85%88%E8%A1%8C%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%B3%95%E5%AE%98%E9%80%90%E5%87%86%E5%88%99%E7%BB%99%E8%AF%81%E6%8D%AE%E4%B8%8E%E5%88%A4%E5%AE%9A%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%A4%9A%E6%AC%A1%E5%88%A4%E5%86%B3%E5%8F%96%E5%A4%9A%E6%95%B0%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%81%9A%E5%90%88%E6%88%90%E5%88%86%E6%95%B0%E6%88%96%E8%83%9C%E8%80%85%22%5D%0A%20%20F%20--%3E%20G%7B%22%E4%B8%8E%E4%BA%BA%E9%87%91%E6%A0%87%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20G%20--%3E%7C%22%E4%B8%80%E8%87%B4%22%7C%20H%5B%22%E8%AE%B0%E5%88%86%22%5D%0A%20%20G%20--%3E%7C%22%E5%88%86%E6%AD%A7%22%7C%20I%5B%22%E9%80%81%E4%BA%BA%E4%BB%B2%E8%A3%81%EF%BC%8C%E5%9B%9E%E6%B5%81%E6%A0%87%E5%AE%9A%E9%9B%86%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"拆准则为什么有效：整体判断让法官同时做事实核对与文风偏好，注意力摊薄后系统性先验（长、列表、自信）占便宜；逐准则判定缩小了每个子任务的输入空间，先验能施加的面也随之变小。准则的本质是操作定义——「有帮助」没法判，「是否答了用户问的两个问题」可以判。拆分还带来可归因性：输在事实准则与输在格式准则，后续动作完全不同。",-1)),E[5]||(E[5]=e("p",null,[a("集成为什么降方差不纠偏差：若两个法官的错误独立，多数投票按误差概率衰减；若错误同源（都偏爱长答案、都出自近亲家族），投票只是把同一票抄三遍。所以集成的第一设计变量是"),e("strong",null,"家族与提示的异质性"),a("，不是数量。微调法官把一致性买在前面：权重固化后提示与温度的抖动变小，但它冻结了某个训练分布的审美，语料与产品换代时必须再标定，不能永续。")],-1)),(r(),B(o,null,{default:A(()=>[s(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%B3%95%E5%AE%98%E9%9B%86%E6%88%90%3A%20%E5%A4%9A%E4%B8%AA%E6%B3%95%E5%AE%98%20%E6%8A%95%E7%A5%A8%E5%AE%9A%E5%A4%BA%22%5D%20--%3E%20Q%7B%22%E9%94%99%E8%AF%AF%E6%9D%A5%E6%BA%90%E7%8B%AC%E7%AB%8B%E5%90%97%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%8B%AC%E7%AB%8B%3A%20%E4%B8%8D%E5%90%8C%E5%AE%B6%E6%97%8F%E4%B8%8E%E6%8F%90%E7%A4%BA%22%7C%20G%5B%22%E8%AF%AF%E5%B7%AE%E6%8C%89%E6%A6%82%E7%8E%87%E8%A1%B0%E5%87%8F%3Cbr%2F%3E%E5%A4%9A%E6%95%B0%E6%8A%95%E7%A5%A8%E9%99%8D%E6%96%B9%E5%B7%AE%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%8C%E6%BA%90%3A%20%E9%83%BD%E5%81%8F%E7%88%B1%E9%95%BF%E7%AD%94%E6%A1%88%3Cbr%2F%3E%E6%88%96%E5%87%BA%E8%87%AA%E8%BF%91%E4%BA%B2%E5%AE%B6%E6%97%8F%22%7C%20B%5B%22%E5%90%8C%E4%B8%80%E7%A5%A8%E6%8A%84%E4%B8%89%E9%81%8D%3Cbr%2F%3E%E5%81%8F%E5%B7%AE%E5%8E%9F%E6%A0%B7%E4%BF%9D%E7%95%99%22%5D%0A%20%20B%20--%3E%20FIX%5B%22%E8%AE%BE%E8%AE%A1%E5%8F%98%E9%87%8F%3A%20%E6%8D%A2%E5%AE%B6%E6%97%8F%E4%B8%8E%E6%8F%90%E7%A4%BA%3Cbr%2F%3E%E8%BF%BD%E6%B1%82%E5%BC%82%E8%B4%A8%E6%80%A7%20%E8%80%8C%E9%9D%9E%E6%95%B0%E9%87%8F%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">Prometheus 把 rubric 与人写反馈做成微调语料，用开源模型当法官，作者报告其与人评的一致率接近当时的 GPT-4。可复现性换到了，代价是评分尺度从此绑定那个训练分布。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>深化不修复无效的 rubric：准则若本身在量文风（「结构清晰」），拆得再细也是偏差的放大器。优化方会读你的准则清单并逐条拟合——Goodhart 在准则层面照样成立，门禁用的 rubric 要留盲层。<span class="marginnote">为什么 rubric 要留盲层：门禁准则一旦公开，优化方会逐条拟合——你要求「包含三步解释」，回答里就长出三步凑数的废话。留一两把不公开的卷子，才分得清「真变好」与「学会应试」，道理同考试院不公布全部题库。</span>成本也翻倍：逐准则加自采样，一次判决的前向是朴素法官的十倍量级，这笔预算要进组合课的账。最后，一致率高不等于测对了构念：法官与人可以在「都偏爱长答案」上一致；效度要靠准则与声明的对表，不是一致率单独能给的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>法官深化的方向：准则操作化、判决结构化、对人标定；换序控长只是前提不是深化。</li><li>程序可判定的子集先行，法官只接直觉判不了的部分。</li><li>集成降方差靠异质性；微调法官固化尺度，换代要再标定。</li><li>一致率 \\(\\kappa\\) 是标定证据，不是效度证据；构念对表另行声明。</li><li>出处：Zheng 等 2023（MT-Bench 与法官偏差）；Zhu 等 JudgeLM 2023；Kim 等 Prometheus 2023；Li 等 Auto-J 2023，按本课程整理。</li></ul>',5))])}const c=n(p,[["render",m]]);export{f as __pageData,c as default};
